-- Processos da Empresa: tutoriais do sistema atualizados com as funcionalidades novas e cinco tutoriais novos
-- (SIS-20 Cotações, SIS-21 Vendas, SIS-22 Folha de Campo, SIS-23 Folha Administrativa, SIS-24 Ausência combinada).
-- Tutorial ainda na versão original e sem rascunho → publica uma nova versão (a anterior fica no histórico).
-- Tutorial já editado pela empresa → a atualização entra como rascunho enviado para aprovação (nada publicado é sobrescrito).
CREATE TABLE _sis_upd (code TEXT PRIMARY KEY, content TEXT NOT NULL, note TEXT NOT NULL, is_new INTEGER NOT NULL);
INSERT INTO _sis_upd VALUES ('SIS-02', '{"title":"Meu painel e Visão da empresa","area":"Sistema · Gestão de Obras","frequency":"Diária","objective":"Acompanhar diariamente as próprias tarefas, conferências, férias, ausências e reembolsos (Meu painel) e o panorama geral da empresa (Visão da empresa).","erp_module":"Charão Gestão → Meu painel / Visão da empresa","links":[{"kind":"link","label":"Abrir Meu painel","url":"https://charao-gestao.onrender.com/#/painel"}],"inputs":"Tarefas cadastradas e atribuídas.","outputs":"Prioridades do dia definidas; atrasos e conferências pendentes identificados.","rules":"Comece o dia pelo Meu painel: atrasadas e as que vencem em 7 dias primeiro.\nAs listas ficam recolhidas: o cabeçalho mostra o que há dentro e o sinal ⚠ quando há algo importante (atrasos, NC em aberto, pendências). Toque no cabeçalho para abrir; o sistema lembra a escolha enquanto você estiver conectado.\nCada quadro tem o botão PDF para extrair só aquele visual.\nA Visão da empresa só aparece para quem tem a seção liberada.","indicators":["Pontualidade (entregas no prazo)","Tarefas atrasadas","Tarefas em conferência"],"steps":[{"responsible":"Usuário","activity":"Abre o Meu painel","details":"- Indicadores: em aberto, atrasadas, vencem em 7 dias, em conferência, pontualidade e concluídas\n- Indicadores de execução: média de dias, tarefas antecipadas e atraso de preenchimento","control":false,"fail":null,"back_to":null},{"responsible":"Usuário","activity":"Planeja a semana","details":"- **Planejamento da semana**: tarefas por dia, com a cor de cada projeto\n- Tarefas de vários dias aparecem em faixa contínua; use **Mostrar/Ocultar subtarefas**","control":false,"fail":null,"back_to":null},{"responsible":"Usuário","activity":"Trata primeiro as atrasadas e as que vencem nos próximos 7 dias","details":"Blocos **Minhas atrasadas** e **Próximos 7 dias** (ficam sempre abertos). Toque na tarefa para executar, registrar avanço ou reagendar (SIS-05 e SIS-06).","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Responsável do projeto","activity":"Confere as entregas em “Para conferir”","details":"- Entregas da equipe e dos projetos em que você é o responsável\n- **Aprovar** com um toque ou **Devolver** com o motivo, sem abrir a tarefa","control":false,"fail":null,"back_to":null},{"responsible":"Usuário","activity":"Acompanha férias, ausências combinadas e reembolsos","details":"- **Minhas férias**: saldo e **Solicitar férias** (SIS-16)\n- **Ausências combinadas**: **Combinar ausência** (SIS-24)\n- **Meus reembolsos**: **Lançar reembolso** com o comprovante (pago na Folha Administrativa, SIS-23)","control":false,"fail":null,"back_to":null},{"responsible":"Usuário","activity":"Consulta o desempenho e a Corrida dos indicadores","details":"- **Meu desempenho completo**: histórico de entregas e pontualidade\n- **Corrida dos indicadores**: você comparado com a empresa, mês a mês; quadros piores que a média ficam destacados","control":false,"fail":null,"back_to":null},{"responsible":"Gestor","activity":"Acompanha a equipe","details":"Bloco **Desempenho da equipe**: carga e situação por integrante, atrasadas da equipe, ranking e prazos e repactuações.","control":false,"fail":null,"back_to":null},{"responsible":"Diretoria / Gestor","activity":"Acompanha a Visão da empresa","details":"- Análise por tipo de projeto, conclusão por projeto e evolução da empresa\n- Desempenho por usuário, atrasos com maior impacto, prazos e repactuação\n- Atrasos críticos, próximos 7 dias e atividade recente","control":false,"fail":null,"back_to":null}],"related":[14,20]}', 'Atualização: planejamento da semana, Para conferir, Corrida dos indicadores, ausências, reembolsos e listas recolhidas', 0);
INSERT INTO _sis_upd VALUES ('SIS-03', '{"title":"Cadastro de projetos e áreas internas","area":"Sistema · Gestão de Obras","frequency":"Sob demanda","objective":"Cadastrar obras (projetos) e áreas internas, com classificações, opções do projeto (folha de campo e cotações), calendário, alertas dos indicadores e planejamento por planilha.","erp_module":"Charão Gestão → Projetos","links":[{"kind":"link","label":"Abrir Projetos","url":"https://charao-gestao.onrender.com/#/projetos"}],"inputs":"Dados da obra (nome, cliente, endereço, datas), tipo de projeto e modelo de classificação.","outputs":"Projeto cadastrado (PRJ-000) ou área interna (INT-000) pronto para receber tarefas, registros e cronograma.","rules":"Somente gestores, coordenadores e administradores cadastram e editam projetos.\nClassificações com tarefas não podem ser removidas: reclassifique as tarefas antes.\nCotações e folha de campo só existem nos projetos com a opção marcada no cadastro.\nTipos de projeto e modelos de classificação são definidos em Configurações (SIS-18).","indicators":["Tempo decorrido x prazo da obra","Tarefas atrasadas por projeto"],"steps":[{"responsible":"Gestor / Coordenador","activity":"Cria o projeto em Projetos → Novo projeto","details":"- Escolha **Projeto (obra)** ou **Área interna da empresa**\n- O código é gerado automaticamente (PRJ-000 / INT-000)","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Coordenador","activity":"Preenche dados, tipo, datas e local da obra","details":"- Cliente, endereço, responsável (líder), início e término previstos\n- **Estado e município**: trazem os feriados locais para o calendário da obra","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Coordenador","activity":"Marca as opções do projeto","details":"- **Controle de folha de campo**: a obra aparece na Folha de Campo (SIS-22)\n- **Este projeto terá cotações**: libera a área de Cotações (SIS-20). Projetos sem a marcação não têm cotações","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Coordenador","activity":"Define as classificações (Grupo / Local / Etapa)","details":"Use um **modelo de classificação** (ex.: Fundação, Estrutura, Bloco A) ou cadastre as próprias. As tarefas serão organizadas por elas.","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Coordenador","activity":"Importa o planejamento (opcional)","details":"**Importar planejamento**: planilha .xlsx com tarefas, subtarefas, responsáveis, datas e predecessoras/sucessoras (basta informar um dos lados). Há prévia antes de gravar.","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Coordenador","activity":"Confere o calendário e configura os alertas","details":"- **Calendário** (botão no topo): feriados e dias não trabalhados da obra; marque se a obra trabalha num feriado\n- **Alertas**: limites de atenção e crítico de cada indicador do projeto; os cards fora do limite ficam destacados e aparecem no quadro do topo","control":false,"fail":null,"back_to":null},{"responsible":"Administrador","activity":"Libera o acesso das pessoas ao projeto","details":"No cadastro de cada pessoa (Acesso e permissões): acesso total, projetos específicos ou só tarefas próprias.","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Coordenador","activity":"Acompanha o projeto","details":"- Indicadores de execução (e de cotações, quando houver), andamento por classificação, check-lists, registros, cronograma e mapa de vínculos\n- As listas da página ficam recolhidas com o resumo no cabeçalho; toque para abrir\n- Projetos concluídos ficam no filtro **Concluídos**","control":false,"fail":null,"back_to":null}],"related":[13,18,19,27],"section":"projetos"}', 'Atualização: opções de folha de campo e cotações, calendário em botão, alertas e importação de planejamento', 0);
INSERT INTO _sis_upd VALUES ('SIS-04', '{"title":"Criar tarefas e subtarefas","area":"Sistema · Gestão de Obras","frequency":"Diária","objective":"Registrar uma solicitação de trabalho com responsável, prazo, prioridade e o tipo de comprovação exigida na entrega.","erp_module":"Charão Gestão → Tarefas → Nova tarefa (ou pelo projeto)","links":[{"kind":"link","label":"Criar nova tarefa","url":"https://charao-gestao.onrender.com/#/tarefas/nova"}],"inputs":"O que precisa ser feito, projeto, responsável e prazo.","outputs":"Tarefa com código (PRJ-000-00000) atribuída ao responsável e visível no Meu painel dele.","rules":"O prazo é contado em dias úteis pelo calendário da obra e não conta as férias e ausências aprovadas do responsável.\nTarefa principal acompanha as subtarefas: início pela que começa mais cedo, término pela que termina mais tarde, e status e avanço calculados por elas.\nDescreva claramente o resultado esperado e anexe referências (fotos, PDF) quando ajudar.\nDefina a comprovação: nenhuma, somente foto, somente descrição ou foto + descrição.\nExclusão em lote: só o administrador, com as mesmas travas da exclusão individual.","indicators":["Tarefas sem responsável","Tarefas sem prazo"],"steps":[{"responsible":"Solicitante","activity":"Abre Tarefas → Nova tarefa","details":"Também é possível criar a partir da tela do projeto, do plano da semana ou importar várias de uma vez pelo **Importar planejamento** do projeto (SIS-03).","control":false,"fail":null,"back_to":null},{"responsible":"Solicitante","activity":"Escolhe o projeto/área e a classificação","details":"O calendário de dias úteis usado no prazo é o da obra escolhida.","control":false,"fail":null,"back_to":null},{"responsible":"Solicitante","activity":"Preenche título, descrição, responsável, início, prazo e prioridade","details":"- **Prazo**: informe a data ou o número de dias úteis\n- **Prioridade**: baixa, média, alta ou urgente\n- **Sem responsável** só se for definir depois","control":false,"fail":null,"back_to":null},{"responsible":"Solicitante","activity":"Define a comprovação exigida e anexa referências","details":"- **Somente foto**: exige ao menos uma foto da execução\n- **Somente descrição**: exige texto da execução\n- **Foto + descrição**: exige os dois","control":false,"fail":null,"back_to":null},{"responsible":"Solicitante","activity":"Salva; se necessário, cria subtarefas","details":"- Na tarefa salva use **Nova subtarefa** para dividir o trabalho\n- **Duplicar** copia uma tarefa ou subtarefa\n- Para listas de verificação, use **Criar check-list** (SIS-07); para repetição, **Criar tarefa recorrente** (SIS-08)","control":false,"fail":null,"back_to":null}],"related":[14,16,17],"section":"tarefas"}', 'Atualização: importação de planejamento, tarefa principal pelas subtarefas e exclusão em lote', 0);
INSERT INTO _sis_upd VALUES ('SIS-05', '{"title":"Executar e conferir tarefas","area":"Sistema · Gestão de Obras","frequency":"Diária","objective":"Registrar a execução com a comprovação exigida e obter a conferência (aprovação) de quem solicitou ou do gestor.","erp_module":"Charão Gestão → Tarefas → (tarefa)","links":[{"kind":"link","label":"Abrir Tarefas","url":"https://charao-gestao.onrender.com/#/tarefas"}],"inputs":"Tarefa atribuída; fotos e descrição do serviço executado.","outputs":"Tarefa concluída e conferida, com histórico, comprovação e data real de conclusão.","rules":"Somente o responsável registra a execução (o líder registra pelo terceirizado sem acesso).\nConferem a entrega o líder da pessoa e o responsável do projeto; o responsável não confere a própria entrega (exceto administrador e coordenador).\nConferência feita mais de 36 horas depois do envio conta como atraso de preenchimento do líder direto.\nDevolução sempre com o motivo, para o responsável ajustar.\nO administrador pode corrigir datas sem reagendar (fica registrado).","indicators":["Entregas no prazo (%)","Tempo médio em conferência","Devoluções por tarefa"],"steps":[{"responsible":"Responsável da tarefa","activity":"Abre a tarefa e inicia a execução","details":"A tarefa passa de **Aberta** para **Em andamento**. Use **Avanço da tarefa** para informar o percentual quando for longa.","control":false,"fail":null,"back_to":null},{"responsible":"Responsável da tarefa","activity":"Registra a execução","details":"- **Descrição da execução**: serviço realizado, materiais e conferências feitas\n- **Fotos ou PDF**: pela câmera ou galeria\n- **Observação**: pendências ou informações para o conferente","control":false,"fail":null,"back_to":null},{"responsible":"Responsável da tarefa","activity":"Envia para conferência","details":"Botão **Enviar para conferência**. Se a entrega foi em outra data, informe a data real: quem confere autoriza ou define a data.","control":false,"fail":null,"back_to":null},{"responsible":"Quem confere (líder / responsável do projeto)","activity":"Confere a entrega","details":"- Pela tarefa ou direto no **Meu painel → Para conferir**\n- Analisa descrição e fotos\n- **Aprovar e concluir** ou **Devolver para ajustes** (com o motivo)","control":true,"fail":"Devolvida → responsável ajusta e reenvia","back_to":2},{"responsible":"Sistema","activity":"Conclui a tarefa e atualiza indicadores","details":"Data de conclusão, pontualidade e histórico ficam registrados. Gestores podem **Concluir diretamente** quando não há conferência.","control":false,"fail":null,"back_to":null}],"related":[13,15]}', 'Atualização: Para conferir no Meu painel, responsável do projeto confere e regra das 36 horas', 0);
INSERT INTO _sis_upd VALUES ('SIS-06', '{"title":"Reagendar prazo de tarefa","area":"Sistema · Gestão de Obras","frequency":"Sob demanda","objective":"Alterar o prazo de uma tarefa com justificativa, mantendo o histórico de reagendamentos e o indicador de pontualidade confiável.","erp_module":"Charão Gestão → Tarefas → (tarefa) → Reagendar prazo","links":[{"kind":"link","label":"Abrir Tarefas","url":"https://charao-gestao.onrender.com/#/tarefas"}],"inputs":"Novo prazo e justificativa (lista padrão de justificativas).","outputs":"Prazo atualizado com histórico: antes de vencer ou após vencer, motivo e quem alterou.","rules":"Reagende antes de vencer sempre que possível: reagendamentos após o vencimento contam como atraso.\nFérias ou ausência que caem em data de atividade: ajuste o prazo ou mantenha a data com explicação acordada com o líder (SIS-16 e SIS-24).\nTarefas com muitos reagendamentos viram “crônicas” (limite em Configurações).\nAs justificativas são cadastradas em Configurações.","indicators":["Reagendadas antes de vencer","Repactuadas após vencer","Tarefas crônicas"],"steps":[{"responsible":"Gestor / Coordenador","activity":"Abre a tarefa e escolhe Reagendar prazo","details":"Quem pode editar a tarefa (solicitante, gestor, administrador) reagenda.","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Coordenador","activity":"Informa o novo prazo e a justificativa","details":"Selecione a justificativa na lista e, se preciso, complemente com observação.","control":false,"fail":null,"back_to":null},{"responsible":"Sistema","activity":"Registra o reagendamento e empurra as sucessoras","details":"- Fica no histórico: “Reagendada antes de vencer” ou “com o prazo já vencido”\n- Tarefas dependentes (sucessoras) são empurradas sem penalidade (ver SIS-09)\n- Ao **antecipar** o prazo, o sistema oferece puxar as sucessoras o mesmo número de dias, mantendo a duração","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Coordenador","activity":"Acompanha no filtro de tarefas","details":"Em Tarefas use os filtros **Reagendadas**, **Repactuadas após vencer** e **Crônicas**.","control":false,"fail":null,"back_to":null}],"related":[14,18,25]}', 'Atualização: antecipar puxa as sucessoras e conflito com férias/ausências', 0);
INSERT INTO _sis_upd VALUES ('SIS-07', '{"title":"Check-lists de verificação","area":"Sistema · Gestão de Obras","frequency":"Sob demanda","objective":"Verificar itens em campo (Conforme / Não conforme / N/A) com fotos, observações e responsável por item.","erp_module":"Charão Gestão → Tarefas → Nova tarefa → Criar check-list","links":[{"kind":"link","label":"Abrir Tarefas","url":"https://charao-gestao.onrender.com/#/tarefas"}],"inputs":"Lista de itens a verificar (pode vir do modelo de especialidades da obra).","outputs":"Check-list respondido, conferido e impresso (relatório do check-list ou lista de campo).","rules":"Não conforme exige descrição e foto do problema; N/A exige justificativa.\nA regra de fotos vale para o check-list inteiro: obrigatória em todos os itens ou livre escolha.\nCom 100% de avanço o item continua pendente até ser marcado Conforme (ou N/A).\nO check-list abre só com os grupos à mostra: toque no cabeçalho do grupo para ver os itens.","indicators":["% de itens conformes","Não conformidades por check-list"],"steps":[{"responsible":"Solicitante","activity":"Cria o check-list","details":"- **Criar check-list** no lugar de tarefa\n- Cole os itens (um por linha) ou use a lista do modelo de especialidades\n- Agrupe por grupo/local e defina responsável e datas por item","control":false,"fail":null,"back_to":null},{"responsible":"Solicitante / Gestor","activity":"Define a equipe necessária de cada item","details":"- Profissional ou função (é possível cadastrar uma função genérica na hora)\n- Selecione vários itens para definir a equipe de uma vez\n- Prazo em dias e valores por item","control":false,"fail":null,"back_to":null},{"responsible":"Gestor","activity":"Programa o profissional","details":"**Programar profissional**: escolha o dia de início e o intervalo entre itens; as atividades sem data recebem datas em sequência, considerando as outras atividades dele.","control":false,"fail":null,"back_to":null},{"responsible":"Responsável do item","activity":"Verifica cada item em campo","details":"- **Conforme**, **Não conforme** (com descrição e foto) ou **N/A** (com justificativa)\n- Informe o início real do item; fotos de entrada (antes) e de execução","control":false,"fail":null,"back_to":null},{"responsible":"Responsável do item","activity":"Corrige as não conformidades e atualiza o item","details":"Após a correção, marque como Conforme com a foto da correção.","control":false,"fail":null,"back_to":null},{"responsible":"Responsável da tarefa","activity":"Envia o check-list para conferência","details":"Quando todos os itens estão respondidos.","control":false,"fail":null,"back_to":null},{"responsible":"Quem confere (gestor / solicitante)","activity":"Confere e conclui","details":"Aprova ou devolve com o motivo.","control":true,"fail":"Devolvido → corrigir os itens apontados","back_to":5},{"responsible":"Usuário","activity":"Imprime quando necessário","details":"- **Relatório do check-list** (com fotos e agrupamento no topo da página)\n- **Relatório por profissional** e **Lista de campo** (folha compacta para anotação)","control":false,"fail":null,"back_to":null}],"related":[13,20]}', 'Atualização: equipe necessária por item, programação do profissional e relatórios', 0);
INSERT INTO _sis_upd VALUES ('SIS-09', '{"title":"Cronograma (Gantt) e dependências","area":"Sistema · Gestão de Obras","frequency":"Semanal","objective":"Planejar a sequência das tarefas da obra no cronograma e ligar as que dependem umas das outras.","erp_module":"Charão Gestão → Projetos → (projeto) → Cronograma (Gantt)","links":[{"kind":"link","label":"Abrir Projetos","url":"https://charao-gestao.onrender.com/#/projetos"}],"inputs":"Tarefas do projeto com início e prazo.","outputs":"Cronograma visual atualizado, com dependências e marcos (registros) do projeto.","rules":"Dependência é sempre Término → Início (a sucessora só começa depois que a predecessora termina).\nQuando a predecessora atrasa, as sucessoras são empurradas sem penalizar o responsável delas; ao antecipar, é possível puxá-las mantendo a duração.\nSó é possível ligar tarefas, subtarefas e itens de check-list do mesmo projeto.","indicators":["Impacto de atraso nas sucessoras"],"steps":[{"responsible":"Gestor / Coordenador","activity":"Abre o cronograma do projeto","details":"Barras por tarefa, com subtarefas (mostrar/ocultar) e marcos dos registros do projeto.","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Coordenador","activity":"Liga as tarefas dependentes","details":"Na tarefa: **Adicionar predecessora** (o que precisa terminar antes) ou **Adicionar sucessora** (o que só começa depois).","control":false,"fail":null,"back_to":null},{"responsible":"Sistema","activity":"Mostra a situação “Aguardando” nas sucessoras","details":"Enquanto a predecessora não termina, a sucessora aparece como aguardando.","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Coordenador","activity":"Confere o Mapa de vínculos","details":"- **Mapa de vínculos** (botão no projeto): o encadeamento entre tarefas, subtarefas e itens de check-list\n- Use **−**, **+** e **Ajustar** para ver tudo na tela\n- Em cada dependência aparece a data real de conclusão (dias antes/depois do prazo)","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Coordenador","activity":"Revisa semanalmente e reagenda o necessário","details":"Ajustes de prazo seguem o SIS-06; a impressão do relatório pode incluir o Gantt.","control":false,"fail":null,"back_to":null}],"related":[12,15,20],"section":"projetos"}', 'Atualização: mapa de vínculos com escala e datas reais nas dependências', 0);
INSERT INTO _sis_upd VALUES ('SIS-10', '{"title":"Registros do projeto e atas de reunião","area":"Sistema · Gestão de Obras","frequency":"Sob demanda","objective":"Registrar observações, definições, atas de reunião e pendências de cada obra, formando a linha do tempo e a história do projeto.","erp_module":"Charão Gestão → Projetos → (projeto) → Registros","links":[{"kind":"link","label":"Abrir Projetos","url":"https://charao-gestao.onrender.com/#/projetos"}],"inputs":"Informações da obra, reuniões, solicitações do cliente, ocorrências.","outputs":"Linha do tempo do projeto; definições vigentes; tarefas geradas pelas pendências e demandas de ata; atas em PDF.","rules":"Definição nova pode substituir uma anterior (a antiga fica no histórico como substituída).\nTipos que exigem aprovação ficam “Aguardando aprovação” até um gestor aprovar.\nOs tipos de registro e seus ícones são configurados em Configurações.","indicators":["Pendências em aberto","Definições vigentes"],"steps":[{"responsible":"Usuário","activity":"Abre Registros no projeto e escolhe o tipo","details":"Nota, Decisão (definição), Reunião (ata) ou Pendência, conforme os tipos cadastrados.","control":false,"fail":null,"back_to":null},{"responsible":"Usuário","activity":"Preenche o registro","details":"- Data, origem, descrição e anexos\n- **Ata**: participantes, pauta e itens (Informação, Definição ou Demanda com responsável e prazo)\n- Opcional: vincular a tarefas existentes","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Coordenador","activity":"Aprova ou emite","details":"Ao **emitir a ata**, as definições passam a valer. Gerar tarefa das demandas e pendências é uma opção escolhida na criação do registro.","control":false,"fail":null,"back_to":null},{"responsible":"Sistema","activity":"Mostra os registros no Gantt e na História do projeto","details":"Cada tipo tem seu ícone no cronograma; a **História do projeto** conta mês a mês o que aconteceu.","control":false,"fail":null,"back_to":null},{"responsible":"Usuário","activity":"Imprime a ata ou a história","details":"Ata em PDF pelo registro; **História** do projeto (com a opção **Fotos** para incluir as imagens de cada item) em Relatórios (SIS-11).","control":false,"fail":null,"back_to":null}],"related":[12,18,20],"section":"projetos"}', 'Atualização: gerar tarefa como opção e História com fotos', 0);
INSERT INTO _sis_upd VALUES ('SIS-11', '{"title":"Relatórios e impressões","area":"Sistema · Gestão de Obras","frequency":"Semanal/Mensal","objective":"Emitir relatórios em PDF (A4) de projetos, pessoas, equipes e da empresa para acompanhamento e prestação de contas.","erp_module":"Charão Gestão → Relatórios","links":[{"kind":"link","label":"Abrir Relatórios","url":"https://charao-gestao.onrender.com/#/relatorios"}],"inputs":"Escopo (projeto, usuário, gestor/equipe ou empresa), período e nível de detalhe.","outputs":"Documento A4 pronto para imprimir ou salvar em PDF.","rules":"Os relatórios mostram apenas o que o seu usuário pode ver.\nPara enviar ao cliente, prefira o nível Detalhado; use Completo com fotos para comprovação.","indicators":[],"steps":[{"responsible":"Usuário","activity":"Escolhe o tipo de relatório","details":"- **Projeto**: andamento consolidado da obra\n- **Usuário**: desempenho e tarefas de um responsável\n- **Gestor / equipe**: consolidado da equipe\n- **História do projeto**: narrativa cronológica","control":false,"fail":null,"back_to":null},{"responsible":"Usuário","activity":"Define período, nível e agrupamento","details":"- Níveis: **Indicadores**, **Detalhado** ou **Completo com fotos**\n- Agrupar por status e prazo, dia, semana, mês ou classificação\n- Opções de Gantt (recolhido, sem subtarefas)","control":false,"fail":null,"back_to":null},{"responsible":"Usuário","activity":"Gera e confere a pré-visualização","details":"O documento abre em folhas A4 na tela.","control":false,"fail":null,"back_to":null},{"responsible":"Usuário","activity":"Imprime ou salva em PDF","details":"- Botão **Imprimir / Salvar PDF**; também há relatórios direto da lista de Tarefas\n- Em qualquer tela, o botão **PDF** de cada quadro extrai só aquele visual, com as cores da tela\n- Outros documentos: mapa de cotações (SIS-20), folhas e recibos (SIS-22 e SIS-23), boletins de medição (SIS-12)","control":false,"fail":null,"back_to":null}],"related":[11,19],"section":"relatorios"}', 'Atualização: PDF por quadro e demais documentos do sistema', 0);
INSERT INTO _sis_upd VALUES ('SIS-12', '{"title":"Contratos e medições","area":"Sistema · Gestão da Empresa","frequency":"Mensal","objective":"Controlar contratos (Charão e LuS), planilha contratual, medições (boletins), faturamento e recebimento, com lembretes do que está em aberto.","erp_module":"Charão Gestão → Gestão da Empresa → Contratos","links":[{"kind":"link","label":"Abrir Contratos","url":"https://charao-gestao.onrender.com/#/contratos"}],"inputs":"Contrato assinado com itens (planilha contratual) e aditivos; quantidades executadas no mês.","outputs":"Boletim de medição emitido (PDF); faturamento (NF) e recebimento registrados; indicadores de faturado x a receber.","rules":"Acesso restrito: somente usuários com a liberação de Contratos.\nItem já medido não pode ser removido do contrato.\nUma medição emitida pode ser reaberta para correção; boletim já faturado ou recebido só o administrador corrige (**Corrigir medição**, com motivo e auditoria).","indicators":["Medido x contratado","Faturado no mês / no ano","A receber"],"steps":[{"responsible":"Administrativo / Gestor","activity":"Cadastra o contrato e a planilha contratual","details":"Código automático (CT-000), **empresa** (Charão ou LuS), tipo de contrato, cliente, vigência, itens com quantidades e preços; aditivos quando houver.","control":false,"fail":null,"back_to":null},{"responsible":"Administrativo / Gestor","activity":"Acompanha as próximas ações","details":"- Lembrete das **medições em aberto** (inclusive rascunhos) logo abaixo dos cards e na tela de cada contrato\n- Sugestão de medir quem tem saldo e de encerrar o que está 100% medido","control":false,"fail":null,"back_to":null},{"responsible":"Administrativo / Gestor","activity":"Cria a medição do mês","details":"**Criar medição**: quantidades executadas de cada item (até 8 casas decimais), descontos e acréscimos.","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Coordenador","activity":"Confere e emite a medição","details":"**Emitir medição** gera o boletim (PDF) para o cliente.","control":false,"fail":null,"back_to":null},{"responsible":"Financeiro","activity":"Registra o faturamento (NF)","details":"**Registrar faturamento** com o número/data da nota; também é possível faturar sem NF.","control":false,"fail":null,"back_to":null},{"responsible":"Financeiro","activity":"Registra o recebimento","details":"**Registrar recebimento** quando o pagamento entra. O sistema pergunta se cria a tarefa no Financeiro para atualizar o Mais Controle.","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Diretoria","activity":"Analisa por cliente","details":"Tela do cliente (totais, composição e contratos), ranking **Por cliente** e **Importar BMs** das planilhas de recebimentos do financeiro.","control":false,"fail":null,"back_to":null}],"related":[22],"section":"contratos"}', 'Atualização: empresa e tipo, lembrete de medições, faturar sem NF, recebimento com tarefa opcional e tela do cliente', 0);
INSERT INTO _sis_upd VALUES ('SIS-13', '{"title":"Financeiro: lista do mês, planejamento e Mais Controle","area":"Sistema · Gestão da Empresa","frequency":"Mensal","objective":"Controlar as despesas da empresa mês a mês (previsto x realizado), com a lista do mês em checks, o planejamento anual e a integração com o Mais Controle.","erp_module":"Charão Gestão → Gestão da Empresa → Financeiro (integração com o Mais Controle)","links":[{"kind":"link","label":"Abrir Tarefas financeiras","url":"https://charao-gestao.onrender.com/#/financeiro"}],"inputs":"Obrigação (categoria, valor, vencimento e periodicidade) e comprovantes de pagamento.","outputs":"Parcelas pagas com valor e comprovante; análise de gastos x faturado.","rules":"Acesso restrito: somente usuários com a liberação de Financeiro.\nA despesa vence no fim do mês e só fica atrasada depois do 10º dia útil do mês seguinte.\nReal = 0 marca que a previsão não ocorreu no mês (não fica atrasada).\nPagamento lançado por engano pode ser desfeito; tarefa excluída ou cancelada não volta.","indicators":["Parcelas atrasadas","Pagas no mês","Gastos x faturado"],"steps":[{"responsible":"Financeiro","activity":"Cadastra a despesa (tarefa financeira)","details":"**Nova** despesa: tipo, descrição, valor previsto, vencimento, periodicidade (pontual ou recorrente) e responsável. No Mais Controle, a tarefa financeira é a categoria (vínculo pelo nome).","control":false,"fail":null,"back_to":null},{"responsible":"Sistema","activity":"Busca os pagamentos no Mais Controle","details":"Busca automática semanal (segunda-feira). Pagamentos fora do padrão pedem decisão: trazer, não trazer, ajustar no Mais Controle (cria tarefa no INT-001) ou deixar em stand by.","control":false,"fail":null,"back_to":null},{"responsible":"Financeiro","activity":"Trabalha a lista do mês","details":"- Uma tarefa do mês por responsável, com um **check** por despesa\n- **Pagar** (com valor e comprovante), **Vai ter** (confirma que a despesa ocorrerá) ou pular com motivo opcional\n- A tarefa do mês só conclui quando todos os checks estão resolvidos","control":false,"fail":null,"back_to":null},{"responsible":"Sistema","activity":"Pergunta antes de criar tarefas","details":"Parcelas e lançamentos não criam tarefa sozinhos: o sistema pergunta **Criar tarefas?** (Sim/Não, sem resposta padrão).","control":true,"fail":"Respondeu Não → nenhuma tarefa é criada","back_to":null},{"responsible":"Gestor / Diretoria","activity":"Acompanha o planejamento anual e a análise","details":"- Planejamento anual: despesas x 12 meses, previsto e real, saldo do mês e custos de projetos pagos pela empresa\n- **Análise financeira**: gastos x faturado por período","control":false,"fail":null,"back_to":null}],"related":[21],"section":"financeiro"}', 'Atualização: lista do mês com checks, planejamento anual e Mais Controle', 0);
INSERT INTO _sis_upd VALUES ('SIS-15', '{"title":"Organograma","area":"Sistema · Gestão da Equipe","frequency":"Sob demanda","objective":"Visualizar e manter a hierarquia da empresa (quem responde a quem), com função e responsabilidades de cada pessoa.","erp_module":"Charão Gestão → Gestão da Equipe → Organograma","links":[{"kind":"link","label":"Abrir Organograma","url":"https://charao-gestao.onrender.com/#/equipe/organograma"}],"inputs":"Pessoas cadastradas com gestor/líder definido.","outputs":"Organograma atualizado, impresso em PDF quando necessário.","rules":"Acesso pela seção Organograma e Férias.\nO gestor definido no organograma é quem acompanha as tarefas e aprova as férias da pessoa.\nNão é possível criar ciclos (alguém ser gestor do próprio gestor).","indicators":["Pessoas sem função ou responsabilidades","Pessoas sem gestor"],"steps":[{"responsible":"Gestor / Administrador","activity":"Abre o Organograma","details":"Cada cartão mostra foto, nome, função, carga de tarefas e se está de férias. A equipe de campo aparece abaixo do líder (profissionais da Folha de Campo).","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Administrador","activity":"Ajusta a hierarquia arrastando o cartão","details":"Arraste a pessoa para o novo gestor; o sistema pede confirmação.","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Administrador","activity":"Completa função e responsabilidades","details":"Pessoas sem função/responsabilidades aparecem destacadas: complete no Cadastro da Equipe (SIS-17).","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Administrador","activity":"Imprime o organograma","details":"Botão de impressão gera o organograma em página paisagem.","control":false,"fail":null,"back_to":null}],"related":[25,26],"section":"equipe"}', 'Atualização: equipe de campo no organograma', 0);
INSERT INTO _sis_upd VALUES ('SIS-16', '{"title":"Férias: solicitação e aprovação","area":"Sistema · Gestão da Equipe","frequency":"Sob demanda","objective":"Solicitar, aprovar e controlar férias conforme o vínculo (CLT, PJ ou Estagiário), resolvendo as entregas que caem no período.","erp_module":"Charão Gestão → Meu painel (minhas férias) / Gestão da Equipe → Férias","links":[{"kind":"link","label":"Abrir Férias","url":"https://charao-gestao.onrender.com/#/equipe/ferias"}],"inputs":"Período desejado; admissão da pessoa (base dos períodos aquisitivos); tarefas com prazo no período.","outputs":"Férias aprovadas; dias não contados nos prazos das tarefas; entregas reagendadas.","rules":"CLT: até 3 partes; uma com 14 dias ou mais; nenhuma com menos de 5 dias; total de até 30 dias; não iniciar nos 2 dias que antecedem domingo ou feriado.\n**PJ**: descanso remunerado proporcional (2,5 dias por mês desde o início do contrato), em frações livres; pode antecipar.\n**Estagiário**: recesso proporcional; pode antecipar até 5 dias.\nAtividade no período exige novo prazo ou explicação acordada com o líder; só valem quando o gestor aprova.","indicators":["Períodos vencidos","Pessoas de férias no mês"],"steps":[{"responsible":"Colaborador","activity":"Solicita as férias pelo Meu painel","details":"Informe início e quantidade de dias. O sistema confere as regras e mostra avisos.","control":false,"fail":null,"back_to":null},{"responsible":"Colaborador","activity":"Resolve as entregas do período","details":"O sistema lista as atividades com prazo dentro das férias. Para cada uma: **novo prazo** após o retorno **ou** manter a data com a **explicação** acordada com o líder.","control":false,"fail":null,"back_to":null},{"responsible":"Gestor da pessoa","activity":"Analisa a solicitação e as propostas","details":"Vê os reagendamentos propostos e eventuais novos conflitos.","control":true,"fail":"Recusada → colaborador ajusta o período e solicita de novo","back_to":1},{"responsible":"Sistema","activity":"Aplica os novos prazos e bloqueia os dias de férias","details":"Os prazos mudam com a justificativa “Férias do responsável”; os dias de férias não contam no prazo de novas tarefas.","control":false,"fail":null,"back_to":null},{"responsible":"Gestor / Administrador","activity":"Acompanha o mapa de férias","details":"Em **Férias**: mapa do ano, saldos por período e aprovações pendentes.","control":false,"fail":null,"back_to":null}],"related":[15,24]}', 'Atualização: regras por vínculo e conflito com atividades', 0);
INSERT INTO _sis_upd VALUES ('SIS-17', '{"title":"Cadastro da Equipe e acesso ao sistema","area":"Sistema · Gestão da Equipe","frequency":"Sob demanda","objective":"Cadastrar as pessoas da empresa (com ou sem acesso ao sistema), sua função e responsabilidades, e liberar acessos e seções.","erp_module":"Charão Gestão → Gestão da Equipe → Cadastro da Equipe","links":[{"kind":"link","label":"Abrir Cadastro da Equipe","url":"https://charao-gestao.onrender.com/#/equipe/cadastro"}],"inputs":"Dados da pessoa: nome, função, responsabilidades, setor, admissão, gestor; e-mail para quem terá acesso.","outputs":"Pessoa cadastrada no organograma; acesso e permissões configurados.","rules":"Função e responsabilidades são obrigatórias.\nO vínculo define as regras de férias (SIS-16).\nPessoas sem acesso ao sistema também são cadastradas (aparecem no organograma e podem ser responsáveis acompanhadas pelo líder).\nPessoa sem tarefas pode ser excluída permanentemente pelo administrador; as demais são inativadas (histórico preservado).\nAo mudar permissões, a pessoa precisa entrar novamente.","indicators":["Pessoas sem função/responsabilidades"],"steps":[{"responsible":"Administrador / Gestão da Equipe","activity":"Cadastra a pessoa","details":"**Cadastro da Equipe → Nova pessoa** (com ou sem acesso ao sistema): nome, função, responsabilidades, setor, data de admissão, gestor, **vínculo** (CLT, PJ ou Estagiário) e **jornada de trabalho** (dias e turno, usada no calendário da pessoa).","control":false,"fail":null,"back_to":null},{"responsible":"Administrador","activity":"Libera o acesso (se a pessoa usará o sistema)","details":"Em **Acesso e permissões**: e-mail, senha provisória, perfil (Administrador, Gestor, Coordenador, Colaborador) e terceirizado se for o caso.","control":false,"fail":null,"back_to":null},{"responsible":"Administrador","activity":"Define escopo de projetos e seções liberadas","details":"- Escopo: todos os projetos (com ou sem os projetos internos), projetos específicos ou só tarefas próprias\n- Seções: Gestão de Obras, Gestão da Empresa (Vendas, Contratos, Financeiro, Folhas, Processos), Gestão da Equipe e Administração\n- Tela de entrada: Meu painel ou Visão da empresa","control":false,"fail":null,"back_to":null},{"responsible":"Administrador","activity":"Informa e-mail e senha provisória à pessoa","details":"No primeiro acesso a pessoa troca a senha (SIS-01).","control":false,"fail":null,"back_to":null},{"responsible":"Administrador","activity":"Mantém o cadastro atualizado","details":"Mudança de função, gestor, inativação de quem saiu (o histórico é preservado).","control":false,"fail":null,"back_to":null}],"related":[10,24],"section":"equipe|cadastro_usuarios"}', 'Atualização: vínculo, jornada de trabalho e novas seções', 0);
INSERT INTO _sis_upd VALUES ('SIS-20', '{"links":[{"kind":"link","label":"Abrir Projetos","url":"https://charao-gestao.onrender.com/#/projetos"}],"indicators":["% de itens com 3 ou mais propostas","Nº de solicitações com prazo vencido","Itens sem nenhuma solicitação"],"inputs":"Lista de itens a cotar (orçamento ou planilha de cotação), fornecedores e suas propostas.","outputs":"Mapa de cotações com as propostas por item e o valor mediano; Excel e PDF no modelo PLANILHA COTAÇÃO.","rules":"Meta: no mínimo 3 propostas por item.\nToda solicitação precisa da evidência do envio (print ou PDF); as importadas da planilha ficam marcadas como “importadas da planilha”.\nValor mediano = mediana dos preços recebidos do item.\nVale sempre a revisão mais recente da proposta.\nA área de cotações só existe nos projetos marcados no cadastro.","related":[],"title":"Cotações do projeto: solicitar, receber e comparar propostas","area":"Sistema · Gestão de Obras","frequency":"Sob demanda","section":"projetos","objective":"Controlar as cotações de cada item do projeto até ter no mínimo 3 propostas, com a evidência de cada solicitação enviada, e emitir o mapa de cotações (Excel e PDF).","erp_module":"Charão Gestão → Projetos → (projeto) → Cotações","steps":[{"responsible":"Gestor / Coordenador","activity":"Marca no cadastro do projeto “Este projeto terá cotações”","details":"Projetos → (projeto) → **Editar**. Só os projetos marcados mostram o indicador e o card de **Cotações**.","control":false,"fail":null,"back_to":null},{"responsible":"Orçamentista / Suprimentos","activity":"Cadastra os itens a cotar","details":"- No projeto: card **Cotações** → **Abrir mapa de cotações** (ou **Começar as cotações**)\n- **Novo item**: **Disciplina** e **Descrição** (obrigatórios), Código do orçamento, Local, Quantidade, Unidade, Curva ABC e Observação\n- Ou **Importar planilha** (.xlsx no modelo): cada aba vira uma disciplina e cada bloco PREÇO / NOME / CNPJ… vira um item com as propostas","control":false,"fail":null,"back_to":null},{"responsible":"Suprimentos","activity":"Confere o cadastro de fornecedores","details":"**Fornecedores → Novo fornecedor**: Nome (obrigatório), CNPJ, Contato, Telefone, E-mail, Endereço e Disciplinas que atende. O cadastro é único e vale para todos os projetos.","control":false,"fail":null,"back_to":null},{"responsible":"Suprimentos","activity":"Solicita a proposta a cada fornecedor","details":"**Solicitar proposta**:\n- **Fornecedor** e **Itens desta solicitação** (marque um ou vários; dá para marcar a disciplina inteira)\n- **Enviada em**, **Meio** (E-mail, WhatsApp, Portal, Telefone ou Pessoalmente) e **Responder até**\n- **Evidência do envio** (obrigatória): print do e-mail ou do WhatsApp, ou o PDF enviado\n- Solicite a pelo menos 3 fornecedores por item","control":false,"fail":null,"back_to":null},{"responsible":"Suprimentos","activity":"Cobra quem não respondeu no prazo","details":"**Cobrar**: Cobrado em, Meio, **Novo prazo de resposta**, evidência da cobrança (opcional) e observação. Solicitações vencidas aparecem em vermelho no mapa e no projeto.","control":false,"fail":null,"back_to":null},{"responsible":"Suprimentos","activity":"Lança a proposta recebida","details":"- **Lançar proposta**: **Recebida em**, preço de cada item, Validade, Condições e observações e o **Arquivo da proposta**\n- Item sem preço na proposta: deixe em branco (fica “Sem preço neste item”)\n- Nova negociação: **Revisão** cria R01, R02…; vale o preço mais recente\n- Fornecedor que não vai cotar: **Declinou** (motivo opcional); **Reabrir** se ele voltar","control":false,"fail":null,"back_to":null},{"responsible":"Suprimentos / Gestor","activity":"Confere a meta de 3 propostas por item","details":"- Faixas do mapa: **3 ou mais**, **2 propostas**, **1 proposta** e **Nenhuma** (toque para filtrar os itens)\n- Filtros de itens **sem nenhuma solicitação** e **com solicitação vencida**","control":true,"fail":"Item com menos de 3 propostas → solicitar a outros fornecedores","back_to":4},{"responsible":"Gestor / Diretoria","activity":"Acompanha pelo projeto","details":"- Indicador **Cotações**: situação (meta atingida ou faltam N itens), barra das faixas, solicitações recebidas, aguardando e vencidas\n- Card **Cotações** no corpo do projeto, por disciplina\n- Em **Alertas**, defina os limites de atenção e crítico do indicador","control":false,"fail":null,"back_to":null},{"responsible":"Usuário","activity":"Emite o mapa de cotações","details":"- **Exportar Excel**: modelo PLANILHA COTAÇÃO (aba Resumo e uma aba por disciplina; valor mediano em vermelho, calculado por fórmula)\n- **PDF**: mesmo modelo, em A4 paisagem","control":false,"fail":null,"back_to":null}]}', 'Novo tutorial: cotações do projeto', 1);
INSERT INTO _sis_upd VALUES ('SIS-21', '{"links":[{"kind":"link","label":"Abrir Vendas e Prospecção","url":"https://charao-gestao.onrender.com/#/vendas"}],"indicators":["Oportunidades por etapa","Taxa de conversão em contrato"],"inputs":"Contato do cliente, escopo do serviço, propostas enviadas.","outputs":"Oportunidade registrada etapa a etapa; contrato criado ao fechar.","rules":"Seção liberada por padrão só para o administrador.\nCada etapa pode exigir dados próprios antes de avançar.","related":[],"title":"Vendas e Prospecção (funil)","area":"Sistema · Gestão da Empresa","frequency":"Sob demanda","section":"vendas","objective":"Acompanhar as oportunidades de serviço do primeiro contato ao contrato fechado, num funil em colunas.","erp_module":"Charão Gestão → Gestão da Empresa → Vendas e Prospecção","steps":[{"responsible":"Administrador / Comercial","activity":"Cadastra a oportunidade","details":"**Nova oportunidade** (ou **Adicionar** direto na coluna): cliente, serviço e dados da etapa.","control":false,"fail":null,"back_to":null},{"responsible":"Comercial","activity":"Move o cartão entre as colunas","details":"Arraste o cartão (ou **Mover**). Se faltar dado obrigatório da próxima etapa, o cartão mostra **Falta:** e o sistema pede antes de mover (**Salvar e mover**).","control":false,"fail":null,"back_to":null},{"responsible":"Comercial","activity":"Registra observações e propostas","details":"- **Observação da etapa** em cada coluna\n- Propostas com valor, desconto e revisões; o arquivo da proposta é opcional\n- **Histórico** mostra tudo o que aconteceu","control":false,"fail":null,"back_to":null},{"responsible":"Comercial / Diretoria","activity":"Fecha o contrato","details":"Na etapa de contrato fechado use **Criar contrato**: o contrato nasce em Contratos (SIS-12).","control":false,"fail":null,"back_to":null},{"responsible":"Administrador","activity":"Ajusta as colunas do funil","details":"**Colunas → Nova coluna**, renomear e reordenar; **Salvar colunas**.","control":false,"fail":null,"back_to":null}]}', 'Novo tutorial: Vendas e Prospecção', 1);
INSERT INTO _sis_upd VALUES ('SIS-22', '{"links":[{"kind":"link","label":"Abrir Folha de Campo","url":"https://charao-gestao.onrender.com/#/campo"}],"indicators":["Custo de mão de obra por obra/mês","Saldo das empreitadas","Folhas pagas no prazo"],"inputs":"Presença dos profissionais na obra, contratos de empreitada e medições do terceiro (BM).","outputs":"Folha fechada, pagamentos registrados com comprovante, recibos e relatório da obra.","rules":"Valores e fechamento só para quem tem a seção Folha de Campo.\nFolha fechada não muda: use Reabrir.\nDados de pagamento (PIX) são sensíveis: não compartilhe fora do sistema.","related":[],"title":"Folha de Campo: diárias, empreitadas e pagamentos","area":"Sistema · Gestão da Empresa","frequency":"Semanal/Mensal","section":"folha_campo","objective":"Lançar as diárias da mão de obra própria e as empreitadas de cada obra, fechar a folha e pagar cada profissional com recibo e comprovante.","erp_module":"Charão Gestão → Gestão de Obras → Folha de Campo","steps":[{"responsible":"Gestor / Coordenador","activity":"Marca a obra com “Controle de folha de campo”","details":"No cadastro do projeto (SIS-03). Só as obras marcadas aparecem na Folha de Campo.","control":false,"fail":null,"back_to":null},{"responsible":"Administrativo","activity":"Mantém profissionais e empreitadas","details":"- **Profissionais → Novo profissional**: função, líder, obras e chave PIX\n- **Empreitadas → Nova empreitada**: contrato com valor e saldo; **Nova medição** a cada avanço","control":false,"fail":null,"back_to":null},{"responsible":"Encarregado / Administrativo","activity":"Cria a folha do período","details":"**Nova folha**: obra e período → **Criar folha**. Enquanto aberta, **Editar período** ajusta as datas (diárias fora do novo período pedem confirmação).","control":false,"fail":null,"back_to":null},{"responsible":"Encarregado / Administrativo","activity":"Lança as diárias","details":"**Incluir** o profissional e toque no nome para ver ou editar as diárias; **Retirar da folha** quem não trabalhou. **Salvar folha**.","control":false,"fail":null,"back_to":null},{"responsible":"Administrativo","activity":"Confere com a medição do terceiro e dívidas anteriores","details":"Card **Medição do terceiro e dívidas anteriores**: anexe o BM, registre e quite dívidas (com motivo).","control":true,"fail":"Divergência → corrigir as diárias","back_to":4},{"responsible":"Gestor","activity":"Fecha a folha","details":"**Fechar folha → Fechar e gerar pagamento**: o pagamento vai para o Financeiro. **Reabrir** se precisar corrigir.","control":false,"fail":null,"back_to":null},{"responsible":"Financeiro","activity":"Paga cada profissional","details":"- Aba **Pagamentos**: quem recebe, valor e PIX com **copiar** ou **PIX Copia e Cola** já com o valor\n- **Registrar pagamento** com o comprovante; **Pago** por pessoa ou **Marcar todos pagos** (baixa no Financeiro quando todos estão pagos)","control":false,"fail":null,"back_to":null},{"responsible":"Administrativo","activity":"Emite recibos e relatório","details":"- **Recibos**: recibo para assinatura com o comprovante (inclusive PDF) na mesma impressão\n- **Relatório** e **Resumo e análise**: custo por mês, por serviço e por função, destaques e comparação com a medição","control":false,"fail":null,"back_to":null}]}', 'Novo tutorial: Folha de Campo', 1);
INSERT INTO _sis_upd VALUES ('SIS-23', '{"links":[{"kind":"link","label":"Abrir Folha (Administrativa)","url":"https://charao-gestao.onrender.com/#/folha"}],"indicators":["Folha paga até o dia combinado","Reembolsos pendentes"],"inputs":"Pessoas da folha, faltas descontadas, reembolsos aprovados.","outputs":"Folha fechada, pagamentos com comprovante, recibos por pessoa.","rules":"Acesso só para quem tem a seção Folha (Administrativa).\nDados de pagamento e valores são sensíveis: não compartilhe fora do sistema.\nO reembolso é lançado pela pessoa no Meu painel e só é pago quando incluído na folha.","related":[],"title":"Folha Administrativa: cálculo, pagamento e recibos","area":"Sistema · Gestão da Empresa","frequency":"Mensal","section":"folha","objective":"Calcular a folha mensal das pessoas da empresa (bolsa/salário, VT, VR, faltas e reembolsos), pagar por PIX e emitir recibo com comprovante.","erp_module":"Charão Gestão → Gestão da Empresa → Folha (Administrativa)","steps":[{"responsible":"Administrativo","activity":"Mantém as Pessoas da folha","details":"**Pessoas → Incluir pessoa**: tipo, valores (bolsa/salário, VT, VR), **tipo da chave PIX** e chave.","control":false,"fail":null,"back_to":null},{"responsible":"Administrativo","activity":"Cria a folha do mês","details":"**Nova folha → Criar folha**; **Incluir todos** ou **Incluir pessoa**.","control":false,"fail":null,"back_to":null},{"responsible":"Administrativo","activity":"Confere faltas e reembolsos","details":"- Faltas descontadas das ausências combinadas (SIS-24) aparecem na linha da pessoa\n- **Reembolsos aguardando a folha → Incluir na folha**\n- **Salvar e recalcular**","control":false,"fail":null,"back_to":null},{"responsible":"Gestor","activity":"Fecha a folha","details":"**Fechar folha**. **Reabrir** se precisar corrigir.","control":false,"fail":null,"back_to":null},{"responsible":"Financeiro","activity":"Paga cada pessoa","details":"- Quadro de pagamento: PIX com **copiar** ou **PIX Copia e Cola** já com o valor\n- **Registrar pagamento** com o comprovante; **Pago** por pessoa ou **Marcar todos pagos** (pode desfazer)","control":false,"fail":null,"back_to":null},{"responsible":"Administrativo","activity":"Emite os recibos","details":"**Recibo** de uma pessoa ou **Recibos** de todos: o comprovante (inclusive PDF) sai junto, na página seguinte ao recibo.","control":false,"fail":null,"back_to":null}]}', 'Novo tutorial: Folha Administrativa', 1);
INSERT INTO _sis_upd VALUES ('SIS-24', '{"links":[{"kind":"link","label":"Abrir Meu painel","url":"https://charao-gestao.onrender.com/#/painel"}],"indicators":["Reposições cumpridas","Ausências por mês"],"inputs":"Dia da ausência, dia da reposição (quando houver) e o motivo combinado.","outputs":"Ausência aprovada, prazos resolvidos e reposição conferida (ou desconto na folha).","rules":"Reposição em dias inteiros, no máximo até o mês seguinte.\nO dia da ausência não conta nos prazos das tarefas da pessoa.\nFalta descontada aparece na Folha Administrativa (SIS-23).\nEstagiário pode usar dias do recesso (SIS-16), sem reposição e sem desconto.","related":[],"title":"Ausência combinada e reposição","area":"Sistema · Gestão da Equipe","frequency":"Sob demanda","section":null,"objective":"Combinar com o líder uma falta programada, com reposição em outro dia ou desconto na folha, sem prejudicar as entregas.","erp_module":"Charão Gestão → Meu painel → Ausências combinadas","steps":[{"responsible":"Colaborador (ou gestor)","activity":"Combina a ausência","details":"**Combinar ausência**: **Falta com reposição** ou **Falta descontada**, **Dia da ausência**, **Dia da reposição** e **Combinado / motivo**.","control":false,"fail":null,"back_to":null},{"responsible":"Colaborador","activity":"Resolve as atividades do dia","details":"Se houver atividade com prazo no dia da ausência: novo prazo **ou** manter a data com explicação acordada com o líder.","control":false,"fail":null,"back_to":null},{"responsible":"Gestor","activity":"Aprova ou recusa","details":"Bloco **Ausências para aprovar**: **Aprovar** ou **Recusar** (com o motivo). Lançada pelo gestor já fica aprovada.","control":true,"fail":"Recusada → combinar outra data","back_to":1},{"responsible":"Sistema","activity":"Cria a tarefa do dia da reposição","details":"O sistema pergunta (Sim/Não) e, com Sim, cria a tarefa para a pessoa confirmar a presença no dia da reposição.","control":false,"fail":null,"back_to":null},{"responsible":"Gestor","activity":"Confere a reposição","details":"Bloco **Reposições a conferir**: confirma se foi cumprida.","control":true,"fail":"Não cumprida → vira falta descontada na folha","back_to":null}]}', 'Novo tutorial: ausência combinada e reposição', 1);

-- novos tutoriais (só os que ainda não existem)
INSERT OR IGNORE INTO processes (code, status, version, published, published_at)
  SELECT code, 'publicado', 1, content, datetime('now') FROM _sis_upd WHERE is_new = 1;
