-- novos: conteúdo final (com relacionados) e versão 1
UPDATE processes SET published = (SELECT content FROM _sis_upd u WHERE u.code = processes.code)
  WHERE code IN (SELECT code FROM _sis_upd WHERE is_new = 1) AND version = 1 AND draft IS NULL
    AND NOT EXISTS (SELECT 1 FROM process_versions v WHERE v.process_id = processes.id);
INSERT INTO process_versions (process_id, version, content, note, published_at)
  SELECT p.id, 1, p.published, u.note, p.published_at FROM processes p JOIN _sis_upd u ON u.code = p.code
  WHERE u.is_new = 1 AND NOT EXISTS (SELECT 1 FROM process_versions v WHERE v.process_id = p.id);

-- existentes ainda na versão original: nova versão publicada
INSERT INTO process_versions (process_id, version, content, note, published_at)
  SELECT p.id, p.version + 1, u.content, u.note, datetime('now') FROM processes p JOIN _sis_upd u ON u.code = p.code
  WHERE u.is_new = 0 AND p.status = 'publicado' AND p.version = 1 AND p.draft IS NULL AND p.review_status IS NULL;
UPDATE processes SET version = 2, published = (SELECT content FROM _sis_upd u WHERE u.code = processes.code), published_at = datetime('now'), updated_at = datetime('now')
  WHERE code IN (SELECT code FROM _sis_upd WHERE is_new = 0) AND status = 'publicado' AND version = 1 AND draft IS NULL AND review_status IS NULL
    AND EXISTS (SELECT 1 FROM process_versions v WHERE v.process_id = processes.id AND v.version = 2);

-- existentes já editados pela empresa (sem rascunho pendente): atualização como rascunho para o administrador revisar
UPDATE processes SET draft = (SELECT content FROM _sis_upd u WHERE u.code = processes.code), draft_at = datetime('now'), review_status = 'enviado',
    submit_note = 'Atualização automática do sistema: ' || (SELECT note FROM _sis_upd u WHERE u.code = processes.code) || '. Revise e publique (ou devolva).', submitted_at = datetime('now')
  WHERE code IN (SELECT code FROM _sis_upd WHERE is_new = 0) AND version > 1 AND draft IS NULL
    AND published <> (SELECT content FROM _sis_upd u WHERE u.code = processes.code);

DROP TABLE _sis_upd;
